// Code generated by `cargo run -p codegen` — DO NOT EDIT
// Quantity: Level

#![cfg(feature = "electrical")]
#![allow(
    clippy::excessive_precision,
    clippy::unreadable_literal,
    clippy::double_parens,
    unused_parens
)]

use super::{assert_close, F32_TOL, F64_TOL, ROUND_TRIP_TOL};
use qty::*;

#[test]
fn decibels() {
    for v in [1.0, 0.3, -42.75, 1e6, 123456.789] {
        // Generated conversion vs. the upstream formula, verbatim.
        let x: f64 = v;
        let base = x;
        assert_close(Level::from_decibels(v).as_base(), base, F64_TOL);
        let x: f64 = base;
        let back = x;
        assert_close(Level::from_base(base).as_decibels(), back, F64_TOL);
        assert_close(Level::from_decibels(v).as_decibels(), v, ROUND_TRIP_TOL);
        // f32 storage.
        assert_close(
            Level::from_decibels(v as f32).as_base() as f64,
            base,
            F32_TOL,
        );
        assert_close(
            Level::from_base(base as f32).as_decibels() as f64,
            back,
            F32_TOL,
        );
    }
}

#[test]
fn nepers() {
    for v in [1.0, 0.3, -42.75, 1e6, 123456.789] {
        // Generated conversion vs. the upstream formula, verbatim.
        let x: f64 = v;
        let base = (1.0 / 0.115129254) * x;
        assert_close(Level::from_nepers(v).as_base(), base, F64_TOL);
        let x: f64 = base;
        let back = 0.115129254 * x;
        assert_close(Level::from_base(base).as_nepers(), back, F64_TOL);
        assert_close(Level::from_nepers(v).as_nepers(), v, ROUND_TRIP_TOL);
        // f32 storage.
        assert_close(Level::from_nepers(v as f32).as_base() as f64, base, F32_TOL);
        assert_close(
            Level::from_base(base as f32).as_nepers() as f64,
            back,
            F32_TOL,
        );
    }
}

#[test]
fn base_unit_expression() {
    let info = <Level<f64> as Quantity>::INFO;
    let expr = <Level<f64> as Quantity>::BASE_UNIT_EXPR;
    let parsed = UnitExpr::parse("dB")
        .ok()
        .filter(|e| e.dimensions == info.dimensions);
    let from_data: Option<f64> = None;
    if let (Some(parsed), Some(size)) = (parsed, from_data) {
        assert_close(parsed.factor, size, F64_TOL);
    }
    match parsed {
        Some(parsed) => assert_eq!(expr, Some(parsed)),
        None => assert_eq!(expr.map(|e| e.factor), from_data),
    }
    if let Some(expr) = expr {
        assert_eq!(expr.dimensions, info.dimensions);
    }
}

#[cfg(feature = "fixed")]
#[test]
fn fixed_units() {
    use super::{check_fixed, check_fixed_rescale};
    check_fixed::<unit::level::Decibel>();
    check_fixed_rescale::<unit::level::Decibel>();
    check_fixed::<unit::level::Neper>();
    check_fixed_rescale::<unit::level::Neper>();
}

#[test]
fn unit_expressions_agree() {
    super::check_unit_exprs::<Level>(Level::new);
}

#[test]
fn unit_metadata() {
    let info = Level::<f64>::INFO;
    assert_eq!(info.name, "Level");
    assert_eq!(info.units.len(), LevelUnit::ALL.len());
    for (&unit, unit_info) in LevelUnit::ALL.iter().zip(info.units) {
        assert_eq!(unit.info(), unit_info);
        assert_eq!(format!("{unit:?}"), unit_info.singular);
        assert_eq!(unit.abbreviation(), unit_info.abbreviation);
        assert_eq!(unit.all_abbreviations(), unit_info.abbreviations);
    }
    assert_eq!(info.base_unit, LevelUnit::Decibel.info());
}

#[test]
fn new_and_convert_to_match_named_methods() {
    let v = 1234.5;
    assert_eq!(Level::new(v, LevelUnit::Decibel), Level::from_decibels(v));
    assert_eq!(
        Level::from_base(v).convert_to(LevelUnit::Decibel),
        Level::from_base(v).as_decibels()
    );
    assert_eq!(Level::new(v, LevelUnit::Neper), Level::from_nepers(v));
    assert_eq!(
        Level::from_base(v).convert_to(LevelUnit::Neper),
        Level::from_base(v).as_nepers()
    );
}

#[test]
fn const_new_matches_new() {
    const AT_COMPILE_TIME: [Level; 2] = [
        Level::const_new(1234.5, LevelUnit::Decibel),
        Level::const_new(1234.5, LevelUnit::Neper),
    ];
    for (q, &unit) in AT_COMPILE_TIME.iter().zip(LevelUnit::ALL) {
        assert_eq!(
            q.as_base().to_bits(),
            Level::new(1234.5_f64, unit).as_base().to_bits(),
            "{unit:?}"
        );
    }
    for v in [0.0, -0.0, 1e-300, -2.5, 3.0e8, f64::MAX] {
        for &unit in LevelUnit::ALL {
            assert_eq!(
                Level::const_new(v, unit).as_base().to_bits(),
                Level::<f64>::new(v, unit).as_base().to_bits()
            );
        }
    }
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = Level::from_base(v);
        let auto = q.auto_unit();
        assert_close(Level::new(auto.value, auto.unit).as_base(), v, F64_TOL);
        for &unit in LevelUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(Level::from_base(0.0).auto_unit().unit, LevelUnit::Decibel);
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!("dB".parse::<LevelUnit>(), Ok(LevelUnit::Decibel));
    assert_eq!(
        format!("2.5 {}", "dB").parse::<Level>(),
        Ok(Level::new(2.5, LevelUnit::Decibel))
    );
    assert_eq!("Np".parse::<LevelUnit>(), Ok(LevelUnit::Neper));
    assert_eq!(
        format!("2.5 {}", "Np").parse::<Level>(),
        Ok(Level::new(2.5, LevelUnit::Neper))
    );
    assert_eq!(
        "1 not-a-unit".parse::<Level>(),
        Err(ParseError::UnknownUnit)
    );
}

#[test]
fn parse_every_name() {
    assert_eq!(LevelUnit::from_name("decibel"), Some(LevelUnit::Decibel));
    assert_eq!(LevelUnit::from_name("decibel"), Some(LevelUnit::Decibel));
    assert_eq!(LevelUnit::from_name("DECIBEL"), Some(LevelUnit::Decibel));
    assert_eq!(LevelUnit::from_name("decibels"), Some(LevelUnit::Decibel));
    assert_eq!(LevelUnit::from_name("decibels"), Some(LevelUnit::Decibel));
    assert_eq!(LevelUnit::from_name("DECIBELS"), Some(LevelUnit::Decibel));
    assert_eq!(LevelUnit::from_name("neper"), Some(LevelUnit::Neper));
    assert_eq!(LevelUnit::from_name("neper"), Some(LevelUnit::Neper));
    assert_eq!(LevelUnit::from_name("NEPER"), Some(LevelUnit::Neper));
    assert_eq!(LevelUnit::from_name("nepers"), Some(LevelUnit::Neper));
    assert_eq!(LevelUnit::from_name("nepers"), Some(LevelUnit::Neper));
    assert_eq!(LevelUnit::from_name("NEPERS"), Some(LevelUnit::Neper));
}

#[test]
fn arithmetic_f64() {
    let a = Level::from_base(6.0);
    let b = Level::from_base(2.0);
    assert_eq!((a + b).as_base(), 8.0);
    assert_eq!((a - b).as_base(), 4.0);
    assert_eq!((-a).as_base(), -6.0);
    assert_eq!((a * 2.0).as_base(), 12.0);
    assert_eq!((2.0 * a).as_base(), 12.0);
    assert_eq!((a / 2.0).as_base(), 3.0);
    assert_eq!(a / b, 3.0);
    let mut c = a;
    c += b;
    c -= b;
    c *= 2.0;
    c /= 4.0;
    assert_eq!(c.as_base(), 3.0);
}

#[test]
fn arithmetic_integer() {
    let a = Level::<i64>::from_base(7);
    let b = Level::<i64>::from_base(2);
    assert_eq!(a + b, Level::from_base(9));
    assert_eq!(a % b, Level::from_base(1));
    assert_eq!(a / b, 3);
    assert!(a > b);
    assert_eq!([a, b].iter().sum::<Level<i64>>(), Level::from_base(9));
}
